"""Dialog to create or edit an institution facility."""

from typing import TYPE_CHECKING, Optional

from PySide6.QtWidgets import QDialog

from ttea.controller import InstitutionFacilityEditController
# class generated by pyside6-uic
from ttea.ui import Ui_InstitutionFacilityEditView
from ttea.window import WindowConfig

# Type-checking-only imports, to avoid circular imports at run time
if TYPE_CHECKING:
    from ttea.model import InstitutionFacility


class InstitutionFacilityEditView(
    QDialog, Ui_InstitutionFacilityEditView, WindowConfig
):
    """Modal dialog for creating or editing an institution facility.

    The widgets come from ``Ui_InstitutionFacilityEditView`` (Qt
    Designer); field filling, validation and data extraction are done by
    ``InstitutionFacilityEditController``.

    Parameters
    ----------
    parent : QWidget | None, optional
        Parent widget, usually the list window. Default is None.
    institutionfacility : InstitutionFacility | None, optional
        Institution facility to edit; None opens the dialog in creation
        mode. Default is None.

    Attributes
    ----------
    controller : InstitutionFacilityEditController
        Controller of the dialog.

    Notes
    -----
    The title gets the suffix " - Novo" or " - Editar" (translated with
    ``self.tr()``), and the window is 10% narrower and shorter than the
    parent (``WindowConfig.setup_window``).
    """

    def __init__(
        self,
        parent=None,
        institutionfacility: Optional["InstitutionFacility"] = None,
    ):
        super().__init__(parent)

        self.setupUi(self)

        # Window: title, icon and size relative to the parent
        action = (
            self.tr("Novo") if not institutionfacility else self.tr("Editar")
        )

        # title = parent.parent().windowTitle()
        self.setup_window(
            f"{self.windowTitle()} - {action}",
            self.windowIcon(),
            WindowConfig.DECREMENT_SIZE_PERCENT,
            10,  # percent decrease in width
            10,  # percent decrease in height
            parent,
        )

        # The controller fills the fields when editing
        self.controller = InstitutionFacilityEditController(
            self, institutionfacility
        )
